export async function createJobsTableResult(): Promise<string | { message: string }> {
  return sqlQueryRaw("CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL)", []);
}

export async function queryAllJobRows(): Promise<string | { message: string }> {
  return sqlQueryRaw("SELECT id, name, status, created_at FROM jobs ORDER BY datetime(created_at) DESC", []);
}

export async function fetchAllJobs(): Promise<Array<Job>> {
  return sqlJsonRowsList(await queryAllJobRows());
}

export async function enqueueJob(body: CreateJobBody): Promise<Job> {
  return sqlJsonMemberRow(sqlQueryRaw("INSERT INTO jobs (id, name, status, created_at) VALUES (lower(hex(randomblob(8))), ?, 'pending', datetime('now')) RETURNING id, name, status, created_at", [body.name]));
}

export async function queryJobUnionRowRows(id: string): Promise<string | { message: string }> {
  return sqlQueryRaw("SELECT id, name, status, created_at FROM jobs WHERE id = ? UNION ALL SELECT '__missing__', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM jobs WHERE id = ? LIMIT 1) LIMIT 1", [id, id]);
}

export async function decodeUnionJob(id: string): Promise<Job> {
  return sqlJsonMemberRow(await queryJobUnionRowRows(id));
}

export function jobApiEnvelopeLabel(job: Job): string {
  if (job.id == "__missing__") {
    return pointJsonResponse({ error: "not found" }, 404);
  }
  return pointJsonResponse({ job: job }, 200);
}

export async function markNextPendingRunningResult(): Promise<string | { message: string }> {
  return sqlQueryRaw("UPDATE jobs SET status = 'running' WHERE rowid IN (SELECT rowid FROM jobs WHERE status = 'pending' ORDER BY datetime(created_at) ASC LIMIT 1)", []);
}

export async function completeOldestRunningJobResult(): Promise<string | { message: string }> {
  return sqlQueryRaw("UPDATE jobs SET status = 'completed' WHERE rowid IN (SELECT rowid FROM jobs WHERE status = 'running' ORDER BY datetime(created_at) ASC LIMIT 1)", []);
}

