export function createPointRouteFetchHandler() {
  return async (req) => {
    const url = new URL(req.url);
  if (req.method === "POST" && new RegExp("^\\/api\\/jobs$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/api\\/jobs$"));
    const bodyRecord = await pointBodyRecord(req, ["name"]);
    const handlerResult = postJobRoute(bodyRecord);
    return pointRouteResponse(await handlerResult);
  }
  if (req.method === "GET" && new RegExp("^\\/api\\/jobs$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/api\\/jobs$"));
    const handlerResult = listJobsRoute();
    return pointRouteResponse(await handlerResult);
  }
  if (req.method === "GET" && new RegExp("^\\/api\\/jobs\\/([^\\/]+)$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/api\\/jobs\\/([^\\/]+)$"));
    const handlerResult = getJobRoute(match[1]);
    return pointRouteResponse(await handlerResult);
  }
    return new Response(JSON.stringify({ error: "Not found" }), { status: 404, headers: { "content-type": "application/json" } });
  };
}

